const n="// 传统沙箱脚本 - 使用 registerFunction 注册函数\r\n// 上下文变量：$api, $route, $data, $el, $query, $queryAll, $rebindRules, $refreshData, $dataSet, $call 都已注入\r\n\r\n// 页面初始化\r\nconsole.log('📊 堆叠表头页面已加载 (传统沙箱执行)');\r\nconsole.log('📦 页面数据:', $data);\r\n\r\n// 注册页面函数\r\nregisterFunction('nodeCheck', function(args) {\r\n  // 移除DOM操作（沙箱环境不支持直接DOM访问）\r\n  console.log('🌳 节点选择:', args.node)\r\n});\r\n\r\nregisterFunction('queryCellInfo', function(args) {\r\n  if (args.column.field === 'Status') {\r\n    if (args.data['Status'] === 'Delivered') {\r\n      args.cell.classList.remove('e-inprogress');\r\n      args.cell.classList.add('e-delivered');\r\n    } else {\r\n      args.cell.classList.remove('e-delivered');\r\n      args.cell.classList.add('e-inprogress');\r\n    }\r\n  }\r\n});\r\n\r\nregisterFunction('dataProcess', function(args) {\r\n  const parentNodes = [\r\n    { id: 1, name: 'Order Details', hasChild: true, expanded: true },\r\n    { id: 2, name: 'Shipping Details', hasChild: true, expanded: true },\r\n    { id: 3, name: 'Delivery Status', hasChild: true, expanded: true },\r\n  ];\r\n\r\n  let treeData = [];\r\n\r\n  if (args.columns && args.columns.length) {\r\n    treeData = args.columns.map((column) => {\r\n      let parentId;\r\n      switch (column.field) {\r\n        case 'OrderID':\r\n        case 'OrderDate':\r\n          parentId = 1;\r\n          break;\r\n        case 'ShipCountry':\r\n        case 'Freight':\r\n          parentId = 2;\r\n          break;\r\n        case 'Status':\r\n        case 'Feedback':\r\n          parentId = 3;\r\n          break;\r\n        default:\r\n          break;\r\n      }\r\n      return {\r\n        id: column.uid,\r\n        name: column.headerText,\r\n        pid: parentId,\r\n        isChecked: column.visible\r\n      };\r\n    });\r\n\r\n    const uniquePids = [];\r\n    treeData.forEach((item) => {\r\n      if (uniquePids.indexOf(item.pid) === -1) {\r\n        uniquePids.push(item.pid);\r\n      }\r\n    });\r\n\r\n    const filteredParents = parentNodes.filter((parent) =>\r\n      uniquePids.indexOf(parent.id) !== -1\r\n    );\r\n    treeData.push(...filteredParents);\r\n  } else {\r\n    treeData = [];\r\n  }\r\n\r\n  const fields = {\r\n    dataSource: treeData,\r\n    id: 'id',\r\n    parentID: 'pid',\r\n    text: 'name',\r\n    hasChildren: 'hasChild'\r\n  };\r\n\r\n  return fields;\r\n});\r\n\r\nregisterFunction('columnChooserClose', function() {\r\n  // 移除DOM操作（沙箱环境不支持直接DOM访问）\r\n  console.log('📊 列选择器关闭')\r\n});\r\n\r\nregisterFunction('columnChooserSubmit', function() {\r\n  // 移除DOM操作（沙箱环境不支持直接DOM访问）\r\n  console.log('📊 列选择器提交')\r\n});\r\n\r\n  checkedElements.forEach(item => {\r\n    if (!showColumns.includes(item)) {\r\n      showColumns.push(item);\r\n    }\r\n  });\r\n\r\n  const columnsToUpdate = {\r\n    visibleColumns: showColumns,\r\n    hiddenColumns: uncheckedElements\r\n  };\r\n\r\n  gridInstance.columnChooserModule.changeColumnVisibility(columnsToUpdate);\r\n});\r\n";export{n as default};
